import { defineStore } from 'pinia';
import { api } from 'src/pages/APIs';
import { onApiRegionChange, whenRegionReady } from 'src/pages/api-base-url';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { useDocNetIssueStore } from './docnet-issues.store';
import { useDocNetMissionStore } from './docnet-missions.store';
import { useDocNetInboxStore } from './docnet-inbox.store';
import { useDocNetAgentStore } from './docnet-agents.store';
import { useDocNetEmailStore } from './docnet-email.store';
import { useDocNetProjectStore } from './docnet-projects.store';
import { DocNetGatewayEventType, DocNetWsMessageType } from 'src/types/websocket';
import type { MissionProgressEvent } from 'src/types/websocket';
import { logger } from 'src/utils/logger';

export interface DocNetWsEvent {
  type?: string;
  success?: boolean;
  message?: string;
  session_id?: string;
  org_id?: string;
  timestamp?: string;
  data?: Record<string, unknown>;
}

type MissionEventCallback = (eventType: string, data: MissionProgressEvent) => void;
type IssueEventCallback = (msg: DocNetWsEvent) => void;

const MAX_RECONNECT_DELAY_MS = 30_000;
const BASE_RECONNECT_DELAY_MS = 1_000;
const HEARTBEAT_TIMEOUT_MS = 45_000; // 30s server heartbeat + 15s grace
const AUTH_TIMEOUT_MS = 10_000;

let regionListenerInstalled = false;

export const useDocNetWebSocketStore = defineStore('docnet_websocket', {
  state: () => ({
    socket: null as WebSocket | null,
    connected: false,
    connecting: false,
    authenticated: false,
    sessionId: null as string | null,
    reconnectAttempt: 0,
    reconnectTimer: null as ReturnType<typeof setTimeout> | null,
    heartbeatTimer: null as ReturnType<typeof setTimeout> | null,
    authTimeoutTimer: null as ReturnType<typeof setTimeout> | null,
    /** Per-mission event listeners — keyed by mission_id */
    missionListeners: new Map<string, Set<MissionEventCallback>>(),
    /** Per-issue event listeners — keyed by issue_id */
    issueListeners: new Map<string, Set<IssueEventCallback>>(),
    /** Server-side channel subscriptions — tracks channels to re-subscribe on reconnect */
    activeChannels: new Set<string>(),
    /** Debounce timer for mission re-fetch triggered by issue changes */
    _missionRefetchTimer: null as ReturnType<typeof setTimeout> | null,
  }),

  actions: {
    async connect(): Promise<void> {
      if (this.socket || this.connecting) return;

      const authStore = useAuthTokenStore();
      const orgId = getOrgId();

      let token: string;
      try {
        token = await authStore.getValidatedToken();
      } catch {
        logger.warn('[DocNet WS] Failed to get auth token, skipping connect');
        return;
      }

      if (!token || !orgId) {
        logger.warn('[DocNet WS] Missing token or org_id, skipping connect');
        return;
      }

      await whenRegionReady();

      if (!regionListenerInstalled) {
        regionListenerInstalled = true;
        let lastRegion: string | null = null;
        onApiRegionChange((region) => {
          if (lastRegion === null) {
            lastRegion = region;
            return;
          }
          if (lastRegion === region) return;
          lastRegion = region;
          logger.info('[DocNet WS] Region changed, tearing down socket', { region });
          if (this.socket) this.disconnect();
        });
      }

      this.connecting = true;
      this.authenticated = false;

      const baseUrl = api.docnet_ws;
      const protocol = baseUrl.startsWith('https') ? 'wss' : 'ws';
      const wsPath = baseUrl.replace(/^https?/, protocol);
      const url = `${wsPath}?org_id=${encodeURIComponent(orgId)}`;

      try {
        const socket = new WebSocket(url);

        socket.onopen = () => {
          logger.info('[DocNet WS] Socket open, sending auth token');
          socket.send(token);
          // Timeout if server doesn't respond to auth
          this.authTimeoutTimer = setTimeout(() => {
            if (!this.authenticated && this.connecting) {
              logger.warn('[DocNet WS] Auth timeout');
              socket.close();
            }
          }, AUTH_TIMEOUT_MS);
        };

        socket.onmessage = (event: MessageEvent) => {
          this.resetHeartbeatTimer();
          try {
            const msg: DocNetWsEvent = JSON.parse(event.data);
            this.handleMessage(msg);
          } catch {
            // ignore parse errors
          }
        };

        socket.onclose = () => {
          logger.info('[DocNet WS] Connection closed');
          this.cleanup();
          this.scheduleReconnect();
        };

        socket.onerror = () => {
          // onclose will fire after this
        };

        this.socket = socket;
      } catch {
        this.connecting = false;
        this.scheduleReconnect();
      }
    },

    /** Handle successful authentication (shared by v2 and legacy paths).
     *
     * The server emits BOTH a v2 ``CONNECTED`` event and a legacy
     * ``{success: true}`` envelope on the same connection for backward
     * compatibility.  Without a guard, both invoke ``resubscribeChannels``
     * + ``refetchAll`` on every (re)connect, double-firing channel
     * SUBSCRIBE frames and list refetches.  Skip the second invocation
     * once already authenticated for this socket.
     */
    handleAuthSuccess(sessionId: string | null) {
      if (this.authenticated) {
        if (sessionId && !this.sessionId) this.sessionId = sessionId;
        return;
      }
      this.authenticated = true;
      this.connected = true;
      this.connecting = false;
      this.reconnectAttempt = 0;
      this.sessionId = sessionId;
      this.clearAuthTimeout();
      this.resetHeartbeatTimer();
      this.resubscribeChannels();
      this.refetchAll();
    },

    handleMessage(msg: DocNetWsEvent) {
      // Handle v2 auth response
      if (msg.type === DocNetWsMessageType.CONNECTED) {
        const sessionId = msg.session_id ?? (msg.data?.session_id as string) ?? null;
        logger.info(`[DocNet WS] Authenticated (session: ${sessionId})`);
        this.handleAuthSuccess(sessionId);
        return;
      }

      if (msg.type === DocNetWsMessageType.AUTH_FAILED) {
        logger.warn(`[DocNet WS] Auth failed: ${msg.message ?? (msg.data?.message as string)}`);
        // Server allows 3 attempts then closes — don't close from client side
        return;
      }

      // Handle legacy auth response (success boolean) for backward compat
      if ('success' in msg && !msg.type) {
        if (msg.success) {
          logger.info(`[DocNet WS] Authenticated via legacy (session: ${msg.session_id})`);
          this.handleAuthSuccess(msg.session_id || null);
        } else {
          logger.warn(`[DocNet WS] Auth failed: ${msg.message}`);
        }
        return;
      }

      // Handle channel subscription confirmations
      if (msg.type === DocNetWsMessageType.SUBSCRIBED) {
        const channel = msg.data?.channel as string;
        logger.debug(`[DocNet WS] Subscribed to ${channel}${msg.data?.already_subscribed ? ' (already subscribed)' : ''}`);
        return;
      }

      if (msg.type === DocNetWsMessageType.UNSUBSCRIBED) {
        const channel = msg.data?.channel as string;
        logger.debug(`[DocNet WS] Unsubscribed from ${channel}`);
        return;
      }

      // Handle server error messages
      if (msg.type === DocNetWsMessageType.ERROR) {
        logger.warn(`[DocNet WS] Server error: ${msg.message ?? (msg.data?.message as string)}`);
        return;
      }

      // Respond to server ping with pong to keep connection alive
      if (msg.type === DocNetWsMessageType.PING) {
        this.sendPong();
        return;
      }

      if (msg.type === DocNetGatewayEventType.LIST_CHANGED) {
        const entity = msg.data?.entity as string;
        const action = msg.data?.action as string;
        logger.debug(`[DocNet WS] list_changed: ${entity} ${action}`);
        this.handleListChanged(entity);
      }

      if (msg.type === DocNetGatewayEventType.ISSUE_UPDATED) {
        const issueId = msg.data?.issue_id as string;
        if (issueId) {
          // Targeted update: refresh only the issue that changed and sync it
          // across all lists (issues, missionIssues, myIssues) via
          // _syncIssueInLists. Much cheaper than refetching the whole list.
          const issueStore = useDocNetIssueStore();
          issueStore.refreshIssue(issueId);
          // Issue status changes can cascade to mission status (e.g.
          // in_review → waiting_approval on the mission). Debounce a
          // mission refresh so the currently-viewed mission reflects it.
          // Also refresh the mission-scoped issues list to catch new child
          // issues that weren't in missionIssues yet (refreshIssue only
          // updates existing entries — it doesn't add new ones).
          if (this._missionRefetchTimer) clearTimeout(this._missionRefetchTimer);
          this._missionRefetchTimer = setTimeout(() => {
            const missionStore = useDocNetMissionStore();
            const currentMissionId = missionStore.currentMission?.id;
            if (currentMissionId) {
              missionStore.fetchMission(currentMissionId, true).catch(() => {});
              issueStore.fetchMissionIssues(currentMissionId).catch(() => {});
            }
          }, 500);
        } else {
          // No issue_id in payload — fall back to list refresh
          this.handleListChanged('issues');
        }
      }

      if (msg.type === DocNetGatewayEventType.MISSION_UPDATED) {
        // Per-mission targeted update — mirrors the ISSUE_UPDATED
        // branch above.  The mission list page reads from
        // ``missionStore.missions``; ``refreshMission`` fetches the
        // single mission and ``fetchMission`` syncs it into the
        // cached list (and ``currentMission`` if it matches).  One
        // mission fetch per change instead of the whole list — same
        // scaling rationale as the issue case.  Falls back to a
        // list refresh if the payload lacks ``mission_id`` (defensive
        // — shouldn't happen with the current backend emit).
        const missionId = msg.data?.mission_id as string;
        if (missionId) {
          const missionStore = useDocNetMissionStore();
          missionStore.refreshMission(missionId);
        } else {
          this.handleListChanged('missions');
        }
      }

      if (msg.type === DocNetGatewayEventType.INBOX_ITEM_CREATED) {
        this.handleListChanged('inbox');
      }

      // Route events with issue_id to per-issue listeners (run streaming, issue updates)
      const issueId = msg.data?.issue_id as string;
      if (issueId) {
        const listeners = this.issueListeners.get(issueId);
        if (listeners) {
          for (const cb of listeners) {
            try { cb(msg); } catch { /* ignore */ }
          }
        }
      }

      // Route events with mission_id to per-mission listeners
      const missionId = (msg.data as MissionProgressEvent)?.mission_id;
      if (missionId) {
        const listeners = this.missionListeners.get(missionId);
        if (listeners) {
          for (const cb of listeners) {
            try { cb(msg.type || '', (msg.data || {}) as MissionProgressEvent); } catch { /* ignore */ }
          }
        }
      }
    },

    /** Send a JSON message to the server if the socket is open */
    send(msg: Record<string, unknown>) {
      if (this.socket && this.socket.readyState === WebSocket.OPEN) {
        this.socket.send(JSON.stringify(msg));
      }
    },

    sendPong() {
      this.send({ type: DocNetWsMessageType.PONG });
    },

    /**
     * Subscribe to a server-side channel for targeted event delivery.
     * Channel patterns: "mission:{id}", "issue:{id}", "agents:{org_id}", "emails:{org_id}", "inbox:{org_id}"
     */
    subscribe(channel: string) {
      if (this.activeChannels.has(channel)) return;
      this.activeChannels.add(channel);
      if (this.authenticated) {
        logger.info(`[DocNet WS] Subscribing to ${channel}`);
        this.send({ type: DocNetWsMessageType.SUBSCRIBE, data: { channel } });
      }
    },

    /**
     * Unsubscribe from a server-side channel.
     */
    unsubscribe(channel: string) {
      this.activeChannels.delete(channel);
      if (this.authenticated) {
        logger.info(`[DocNet WS] Unsubscribing from ${channel}`);
        this.send({ type: DocNetWsMessageType.UNSUBSCRIBE, data: { channel } });
      }
    },

    /** Re-subscribe to all active channels after reconnect */
    resubscribeChannels() {
      if (this.activeChannels.size > 0) {
        logger.info(`[DocNet WS] Re-subscribing to ${this.activeChannels.size} channel(s)`);
        for (const channel of this.activeChannels) {
          this.send({ type: DocNetWsMessageType.SUBSCRIBE, data: { channel } });
        }
      }
    },

    handleListChanged(entity: string) {
      switch (entity) {
        case 'issues': {
          const issueStore = useDocNetIssueStore();
          issueStore.fetchIssues(true).catch(() => {});
          if (issueStore.currentIssue?.id) {
            issueStore.fetchIssue(issueStore.currentIssue.id, true).catch(() => {});
          }
          // Issue status changes can cascade to mission status — debounce to avoid
          // redundant fetches during rapid agent processing
          if (this._missionRefetchTimer) clearTimeout(this._missionRefetchTimer);
          this._missionRefetchTimer = setTimeout(() => {
            const missionStore = useDocNetMissionStore();
            const currentMissionId = missionStore.currentMission?.id;
            if (currentMissionId) {
              missionStore.fetchMission(currentMissionId, true).catch(() => {});
              // Also refresh the mission-scoped issues list so sub-issue
              // statuses update in the detail view without a full page reload
              issueStore.fetchMissionIssues(currentMissionId).catch(() => {});
            }
          }, 500);
          break;
        }
        case 'missions':
          useDocNetMissionStore().fetchMissions(true).catch(() => {});
          break;
        case 'inbox':
          useDocNetInboxStore().fetchItems().catch(() => {});
          break;
        case 'agents':
          useDocNetAgentStore().fetchProfiles().catch(() => {});
          break;
        case 'emails':
          useDocNetEmailStore().fetchEmails().catch(() => {});
          break;
        case 'projects':
          useDocNetProjectStore().fetchProjects().catch(() => {});
          break;
      }
      // Also refresh agents (delegation status may have changed)
      if (entity === 'issues' || entity === 'missions') {
        useDocNetAgentStore().fetchDelegationStatus().catch(() => {});
      }
    },

    async refetchAll(): Promise<void> {
      logger.info('[DocNet WS] Re-fetching all lists after reconnect');
      // Redis pub/sub drops messages with no live subscriber, so any
      // mission_progress / agent_complete / inbox event that landed
      // during the disconnect window is gone.  Re-fetch the lists
      // AND the currently-open per-resource pages so their cached
      // state reflects whatever the server emitted while we were
      // offline.  Without re-fetching ``currentMission`` /
      // ``currentIssue``, an open detail page can keep showing
      // ``active`` after a reject+retrigger that flipped the
      // mission to ``waiting_approval`` mid-disconnect.
      const missionStore = useDocNetMissionStore();
      const issueStore = useDocNetIssueStore();
      const currentMissionId = missionStore.currentMission?.id;
      const currentIssueId = issueStore.currentIssue?.id;
      await Promise.allSettled([
        issueStore.fetchIssues(),
        missionStore.fetchMissions(true),
        useDocNetInboxStore().fetchItems(),
        useDocNetAgentStore().fetchProfiles(),
        useDocNetEmailStore().fetchEmails(),
        useDocNetProjectStore().fetchProjects(),
        ...(currentMissionId
          ? [missionStore.fetchMission(currentMissionId, true)]
          : []),
        ...(currentIssueId
          ? [issueStore.fetchIssue(currentIssueId, true)]
          : []),
      ]);
    },

    scheduleReconnect() {
      if (this.reconnectTimer) return;

      const delay = Math.min(
        BASE_RECONNECT_DELAY_MS * Math.pow(2, this.reconnectAttempt),
        MAX_RECONNECT_DELAY_MS,
      );
      this.reconnectAttempt++;

      logger.info(`[DocNet WS] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempt})`);

      this.reconnectTimer = setTimeout(() => {
        this.reconnectTimer = null;
        this.connect();
      }, delay);
    },

    resetHeartbeatTimer() {
      if (this.heartbeatTimer) {
        clearTimeout(this.heartbeatTimer);
      }
      this.heartbeatTimer = setTimeout(() => {
        logger.warn('[DocNet WS] Heartbeat timeout — reconnecting');
        if (this.socket) {
          this.socket.close();
        }
      }, HEARTBEAT_TIMEOUT_MS);
    },

    clearAuthTimeout() {
      if (this.authTimeoutTimer) {
        clearTimeout(this.authTimeoutTimer);
        this.authTimeoutTimer = null;
      }
    },

    /**
     * Full teardown — clears all state including channels and listeners.
     * Call on logout or intentional disconnect. Components must re-subscribe on next mount.
     */
    disconnect() {
      if (this.reconnectTimer) {
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = null;
      }
      this.clearAuthTimeout();
      if (this.heartbeatTimer) {
        clearTimeout(this.heartbeatTimer);
        this.heartbeatTimer = null;
      }
      if (this.socket) {
        this.socket.onclose = null;
        this.socket.close();
        this.socket = null;
      }
      this.connected = false;
      this.connecting = false;
      this.authenticated = false;
      this.sessionId = null;
      this.reconnectAttempt = 0;
      this.activeChannels.clear();
      this.missionListeners.clear();
      this.issueListeners.clear();
    },

    /**
     * Subscribe to run events for a specific issue via the issue:{id} channel.
     * Returns an unsubscribe function.
     *
     * Note: IssueDetail and RunDetail both use this for the same issue but listen
     * for different event types. They are on exclusive routes (never mounted simultaneously).
     */
    onIssueEvent(issueId: string, callback: IssueEventCallback): () => void {
      if (!this.issueListeners.has(issueId)) {
        this.issueListeners.set(issueId, new Set());
      }
      const listeners = this.issueListeners.get(issueId)!;
      listeners.add(callback);

      // Subscribe to server channel when first listener registers
      if (listeners.size === 1) {
        this.subscribe(`issue:${issueId}`);
      }

      return () => {
        const set = this.issueListeners.get(issueId);
        if (set) {
          set.delete(callback);
          if (set.size === 0) {
            this.issueListeners.delete(issueId);
            this.unsubscribe(`issue:${issueId}`);
          }
        }
      };
    },

    /**
     * Subscribe to mission progress events for a specific mission.
     * Also subscribes to the server-side mission channel for targeted delivery.
     * Returns an unsubscribe function.
     */
    onMissionEvent(missionId: string, callback: MissionEventCallback): () => void {
      if (!this.missionListeners.has(missionId)) {
        this.missionListeners.set(missionId, new Set());
      }
      const listeners = this.missionListeners.get(missionId)!;
      listeners.add(callback);

      // Subscribe to server channel when first listener registers
      if (listeners.size === 1) {
        this.subscribe(`mission:${missionId}`);
      }

      return () => {
        const set = this.missionListeners.get(missionId);
        if (set) {
          set.delete(callback);
          if (set.size === 0) {
            this.missionListeners.delete(missionId);
            this.unsubscribe(`mission:${missionId}`);
          }
        }
      };
    },

    /** Connection-level cleanup — preserves activeChannels and listeners for reconnect */
    cleanup() {
      this.clearAuthTimeout();
      if (this.heartbeatTimer) {
        clearTimeout(this.heartbeatTimer);
        this.heartbeatTimer = null;
      }
      if (this.socket) {
        this.socket.onopen = null;
        this.socket.onmessage = null;
        this.socket.onclose = null;
        this.socket.onerror = null;
        this.socket = null;
      }
      this.connected = false;
      this.connecting = false;
      this.authenticated = false;
      this.sessionId = null;
    },
  },
});
